  left=w.overlay.Left;var textAnchor=w.overlay.TextScreenAnchor;var lockButton=Visuals<Button>(w.overlay).Single(b=>b.ToolTip?.ToString()?.StartsWith("锁定并")==true);await ClickElement(lockButton);await Delay(130);Check("操作按钮不拖动且锁定移除黑底保持穿透",Math.Abs(w.overlay.Left-left)<1&&!w.overlay.Editing&&w.overlay.TransparentSurface&&w.overlay.NativeClickThrough&&w.overlay.NativeNoActivate);Check("编辑锁定切换保持歌词文字位置",Math.Abs(w.overlay.TextScreenAnchor.Y-textAnchor.Y)<1,$"deltaY={w.overlay.TextScreenAnchor.Y-textAnchor.Y}");
  var host=new Window{Width=1000,Height=500,Left=90,Top=140,WindowStyle=WindowStyle.None,Topmost=true,Background=new SolidColorBrush(Color.FromRgb(37,54,73)),ShowInTaskbar=false};int clicks=0;host.MouseDown+=(_,_)=>clicks++;host.Show();host.Activate();w.overlay.Left=140;w.overlay.Top=240;w.overlay.Width=800;w.overlay.ShowPassive();w.overlay.SetText("锁定透明歌词 · 鼠标继续操作背景");await Delay(150);var foreground=NativeProbe.GetForegroundWindow();var rect=w.overlay.GlyphBounds;var p=w.overlay.PointToScreen(new Point(rect.Left+rect.Width/2,rect.Top+rect.Height/2));NativeProbe.SetCursorPos((int)p.X,(int)p.Y);await Delay(200);Check("锁定悬停显示独立解锁图标且不抢焦点",w.overlay.UnlockVisible&&NativeProbe.GetForegroundWindow()==foreground&&w.overlay.NativeClickThrough);
  NativeProbe.ClickAt((int)p.X,(int)p.Y);await Delay(120);Check("锁定文字和矩形区域仍真实鼠标穿透",clicks>0&&NativeProbe.GetForegroundWindow()==foreground);var unlock=w.overlay.UnlockButton;var up=unlock.PointToScreen(new Point(unlock.ActualWidth/2,unlock.ActualHeight/2));NativeProbe.SetCursorPos((int)up.X,(int)up.Y);await Delay(220);Check("从文字移到解锁图标保持可见",w.overlay.UnlockVisible);NativeProbe.ClickAt((int)up.X,(int)up.Y);await Delay(160);Check("原生点击小图标恢复编辑黑底",w.overlay.Editing&&!w.overlay.NativeClickThrough&&!w.overlay.TransparentSurface);
  w.overlay.EndEditing();NativeProbe.SetCursorPos(30,30);await Delay(850);Check("离开后解锁图标淡出且文字仍穿透",!w.overlay.UnlockVisible&&w.overlay.NativeClickThrough);w.overlay.Hide();host.Close();w.Activate();await ClickElement(w.DesktopLyricsButton);Check("关闭后重新打开仍默认可编辑",w.overlay.Editing);w.overlay.Save();w.Save();var saved=State.Read<Settings>("settings.json");Check("桌面位置大小及样式落盘",Math.Abs(saved.OverlayLeft-w.overlay.Left)<1&&saved.OverlayFont==36&&saved.OverlayColor=="#FFE2AB");Snapshot(w.overlay,Path.Combine(State.Home,"desktop-edit.png"));w.overlay.EndEditing();Snapshot(w.overlay,Path.Combine(State.Home,"desktop-locked.png"));w.overlay.Hide();
